(function(){
  const pages=['Project manager'];
  const phases=[['design','Design and documentation'],['consent','Consent and site readiness'],['foundation','Foundations'],['kitset','Kitset delivery and shell'],['fitout','Internal fit-out'],['handover','Completion and handover']];
  const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Pacific/Auckland',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
  const safeDate=d=>/^\d{4}-\d{2}-\d{2}$/.test(d)&&new Date(d+'T12:00:00Z').toISOString().slice(0,10)===d&&d<=today();
  function setup(c){if(!Array.isArray(c.store.projectPhaseReviews))c.store.projectPhaseReviews=[];return c.projects.find(p=>p.id===c.projectId)||c.project||c.projects[0];}
  function projectPhases(c,p){const packages=(c.store.tenderPackages||[]).filter(x=>x.projectId===p.id),list=packages.flatMap(x=>(x.milestones||[]).map((m,i)=>({id:x.id+':'+(m.id || i),name:typeof m==='string'?m:m.name||m.title||m.label||`Milestone ${i+1}`})));return list.length?list:phases.map(([id,name])=>({id,name}));}
  function latestReviews(c,pid){const all=c.store.projectPhaseReviews.filter(x=>x.projectId===pid),latest=new Map();all.forEach(x=>latest.set(x.phaseId,x));return latest;}
  function appendReview(c,d){const p=setup(c),available=projectPhases(c,p);if(c.role!=='contractor')throw Error('Only the contractor role can record a demo coordination review.');if(!available.some(x=>x.id===d.phaseId)||!['pass','fail'].includes(d.result)||!d.reviewer?.trim()||!d.summary?.trim()||!safeDate(d.reviewDate))throw Error('Choose a phase, pass/fail result, reviewer, valid review date and documented summary.');if(d.summary.length>4000||d.reviewer.length>160)throw Error('Review fields exceed their limits.');const earlier=latestReviews(c,p.id).get(d.phaseId),record={id:'pm-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),projectId:p.id,phaseId:d.phaseId,phaseName:available.find(x=>x.id===d.phaseId).name,reviewer:d.reviewer.trim(),reviewDate:d.reviewDate,result:d.result,summary:d.summary.trim(),revision:earlier?earlier.revision+1:1,supersedes:earlier?.id || null,createdAt:new Date().toISOString(),reviewType:'Internal coordination review — not statutory certification'};c.store.projectPhaseReviews.push(record);return record;}
  function render(page,c){const p=setup(c),e=c.escape,list=projectPhases(c,p),latest=latestReviews(c,p.id),all=c.store.projectPhaseReviews.filter(x=>x.projectId===p.id),failed=[...latest.values()].filter(x=>x.result==='fail');return `<div class="shpm-workspace"><div class="heading"><div><div class="eyebrow">SHP 1.3 / PROJECT COORDINATION</div><h1>Project manager</h1><p>${e(p.name)} · ${e(p.id)} · ${e(p.client || '')}</p></div></div><section class="card shpm-notice"><h2>Document each phase decision</h2><p>Internal project coordination reviews record whether the reviewed phase meets the agreed management scope. They are not council building inspections, engineering certification, consent approvals or proof that statutory requirements are satisfied. A pass does not automatically approve the next construction stage.</p><p>Demo reviews are saved in this browser. Earlier entries are retained when a later review supersedes them; production needs authenticated reviewers, server permissions and audit storage.</p></section><section class="card"><h2>${failed.length} outstanding failed phase review${failed.length===1?'':'s'}</h2>${failed.map(x=>`<article class="shpm-outstanding"><strong>${e(x.phaseName)} — action required</strong><p>${e(x.summary)}</p><span class="small">${e(x.reviewer)} · ${e(x.reviewDate)} · revision ${x.revision}</span></article>`).join('') || '<p>No latest phase reviews are marked fail. Unreviewed phases remain unreviewed.</p>'}</section><section class="card"><h2>Project phase status</h2><p>Phases use this project’s tender-package milestones when available; otherwise they are a draft coordination template to align with the agreed project programme. Displayed phases do not claim actual work completion.</p><div class="shpm-phases">${list.map(x=>{const r=latest.get(x.id);return `<article><h3>${e(x.name)}</h3><span class="tag ${r?.result==='fail'?'amber':'grey'}">${r?e(r.result.toUpperCase()):'Not reviewed'}</span>${r?`<p>${e(r.summary)}</p><span class="small">${e(r.reviewer)} · ${e(r.reviewDate)} · revision ${r.revision}</span>`:'<p>A documented review is still required.</p>'}</article>`;}).join('')}</div></section>${c.role==='contractor'?`<form class="card shpm-form" id="shpm-review"><h2>Record a phase review</h2><label>Project<input value="${e(p.name+' · '+p.id)}" readonly></label><label>Phase<select name="phaseId" required>${list.map(x=>`<option value="${e(x.id)}">${e(x.name)}</option>`).join('')}</select></label><label>Reviewer name<input name="reviewer" maxlength="160" required></label><label>Review date<input name="reviewDate" type="date" value="${today()}" max="${today()}" required></label><label>Decision<select name="result" required><option value="">Choose pass or fail</option><option value="pass">Pass — reviewed coordination scope</option><option value="fail">Fail — outstanding action required</option></select></label><label class="shpm-summary">Documented summary (required)<textarea name="summary" maxlength="4000" required placeholder="Record evidence reviewed, work checked, outstanding issues and next actions."></textarea></label><p>A new review is appended; existing history is preserved. No external notifications or automatic approvals are generated.</p><button class="primary">Save review to demo history</button></form>`:'<section class="card"><p>Read-only project coordination view. The contractor preview can append documented reviews.</p></section>'}<section class="card"><h2>Review history</h2>${[...all].reverse().map(r=>`<article class="shpm-history"><strong>${e(r.phaseName)} · ${e(r.result.toUpperCase())} · revision ${r.revision}</strong><p>${e(r.summary)}</p><p class="small">Reviewer ${e(r.reviewer)} · reviewed ${e(r.reviewDate)} · recorded ${e(r.createdAt)}${r.supersedes?' · supersedes '+e(r.supersedes):''}</p></article>`).join('') || '<p>No phase reviews recorded for this project.</p>'}</section></div>`;}
  function bind(page,c){const form=document.querySelector('#shpm-review');if(form)form.onsubmit=ev=>{ev.preventDefault();try{appendReview(c,Object.fromEntries(new FormData(form)));c.save();c.toast('Phase review added; previous history retained');c.navigate(page);}catch(err){c.toast(err.message);}};}
  window.SHProjectManagement={pages,render,bind,appendReview};
})();
